def _capture_stdout(callable_obj, argv: Sequence[str]) -> tuple[int, str]:
    buf = io.StringIO()
    with contextlib.redirect_stdout(buf):
        rc = callable_obj(list(argv))
    return int(rc), buf.getvalue()


def _print_text(text: str) -> None:
